{
  "assay_type": "biochemical kinase inhibition (luminescence, ADP‑Glo)",
  "system": "recombinant human ACVR1 (Activin receptor type‑1, Q04771) purified kinase domain",
  "readout": "luminescence proportional to ADP production (inverse of kinase activity)",
  "steps": [
    {
      "card_id": "kinase-prepare",
      "instruction": "Prepare a 8‑point, 3‑fold serial dilution of MOMELOTINIB (CHEMBL1078178) in assay buffer with 0.5 % DMSO final vehicle fraction; include a DMSO‑only vehicle control and a reference inhibitor control (e.g., LDN‑193189).",
      "parameters": {
        "top_concentration_uM": "10 µM (commonly used upper limit for kinase screens)",
        "dilution_factor": "3",
        "n_points": "8",
        "replicates": "3",
        "vehicle_fraction": "0.5 % (v/v) DMSO"
      }
    },
    {
      "card_id": "kinase-react",
      "instruction": "Add recombinant ACVR1 (enzyme), a peptide substrate (e.g., casein‑derived peptide), and ATP to each well; incubate under conditions justified by published ACVR1 assays.",
      "parameters": {
        "enzyme_concentration": "5 nM (typical for linear reaction range)",
        "substrate_concentration": "10 µM (≈ Km for peptide substrate in ALK2 assays)",
        "ATP_concentration": "10 µM (near Km for ATP in ALK family kinases, as used in CHEMBL1614712 assay)",
        "reaction_time": "30 min (consistent with radiometric ACVR1 assay in CHEMBL1614712)",
        "temperature": "30 °C (standard for kinase biochemical assays)"
      }
    },
    {
      "card_id": "kinase-detect",
      "instruction": "Terminate the reaction with ADP‑Glo™ stop‑and‑detect reagents, deplete remaining ATP, then add detection reagent and measure luminescence.",
      "parameters": {
        "reagent_volumes": "50 µL stop solution + 50 µL detection solution per 50 µL reaction (per ADP‑Glo protocol)",
        "depletion_time": "30 min (per manufacturer recommendation)",
        "detection_time": "10 min (luminescence stabilization period)"
      }
    },
    {
      "card_id": "analyse",
      "instruction": "Normalize luminescence to 0 % activity (no‑compound control) and 100 % activity (vehicle control); fit a four‑parameter logistic curve; report IC₅₀ with 95 % confidence interval and note assay limitations.",
      "parameters": {
        "fit_model": "four‑parameter logistic (Hill slope constrained between 0.5–2)",
        "acceptance_criteria": "R² > 0.90, Hill slope within expected range, CV < 15 % across replicates"
      }
    }
  ],
  "top_concentration_uM": 10,
  "dilution_factor": 3,
  "n_points": 8,
  "replicates": 3,
  "controls": [
    "DMSO vehicle (0.5 % v/v)",
    "Reference inhibitor (LDN‑193189, known ACVR1 inhibitor)",
    "No‑enzyme blank (background luminescence)"
  ],
  "rationale": "A purified ACVR1 kinase assay directly measures target‑specific enzymatic inhibition, matching the question’s focus on biochemical inhibition. The ADP‑Glo luminescent format provides a homogeneous, high‑throughput readout compatible with the provided step cards. Concentration‑response parameters (10 µM top, 3‑fold dilution, 8 points, triplicate) are standard for initial profiling and ensure coverage of the expected potency range without exceeding solubility limits. Reaction time (30 min) and ATP concentration (10 µM) are taken from the only ACVR1‑specific example in the packet (CHEMBL1614712) and from ALK2 assays (CHEMBL1230714, CHEMBL136106) that use similar kinase families, supporting their relevance. Controls allow calculation of percent inhibition and detection of assay drift.",
  "citations": [
    "CHEMBL1614712",
    "CHEMBL1230714",
    "CHEMBL136106"
  ],
  "limitations": [
    "The exact kinetic parameters (Km for ATP, substrate) of the recombinant ACVR1 preparation are not provided; ATP concentration is assumed near Km based on related ALK family data.",
    "Solubility of MOMELOTINIB above 10 µM has not been experimentally confirmed; higher concentrations may precipitate.",
    "No cell‑based confirmation is included; the assay measures only biochemical inhibition and cannot address cellular permeability or off‑target effects.",
    "Reference inhibitor potency on this exact ACVR1 construct is not documented in the packet; it is used as a qualitative control only."
  ]
}
